def make(n):
    """Generate up to 8 distinct expressions; each grows with n."""
    out = []
    for i in range(min(max(n, 1), 8)):
        # a simple unique expression, padded to length ~n
        base = f"x{i}+{i}*y{i}"
        if n > 0:
            base += "+0" * (n // 2)
        out.append([base])
    return out
